script:
const container = root_element.querySelector(".epasi-today");
const money = (value) => format_currency(value || 0);
const escape = (value) => frappe.utils.escape_html(value || "");

function render_section(section) {
	const rows = section.rows
		.map(
			(row) => `<li><a href="/app/${frappe.router.slug(row.document_type)}/${row.document}">
				${escape(row.party)} <small>${escape(row.document)}</small></a><span>${money(row.amount)}</span></li>`
		)
		.join("");
	return `<section>
		<header><b>${__(section.label)} (${section.count})</b><span>${money(section.total)}</span></header>
		<ul>${rows || `<li class="muted">${__("None")}</li>`}</ul>
	</section>`;
}

function render_month(month) {
	const labels = { lent: __("Lent"), collected: __("Collected"), net_profit: __("Net Profit") };
	const rows = Object.entries(labels)
		.map(([key, label]) => {
			const [current, previous] = month[key];
			const change = previous ? Math.round(((current - previous) / Math.abs(previous)) * 100) : null;
			const badge = change === null ? "" : `<em class="${change >= 0 ? "up" : "down"}">${change >= 0 ? "+" : ""}${change}%</em>`;
			return `<li>${label}<span>${money(current)} ${badge}</span></li>`;
		})
		.join("");
	return `<section><header><b>${__("This month vs last month")}</b></header><ul>${rows}</ul></section>`;
}

frappe.call("epasi.api.dashboard.get_today_summary").then(({ message }) => {
	container.innerHTML = `<h4>${__("Today")}, ${frappe.datetime.str_to_user(message.date)}</h4>
		<div class="grid">${message.sections.map(render_section).join("")}${render_month(message.month)}</div>`;
});

style:
.epasi-today { padding: 16px; border: 1px solid var(--border-color); border-radius: var(--border-radius-lg, 12px); background: var(--card-bg); color: var(--text-color); font-size: var(--text-base, 14px); }
.epasi-today h4 { margin: 0 0 12px; font-size: var(--text-lg, 16px); }
.epasi-today .grid { display: grid; gap: 12px; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); }
.epasi-today section { padding: 12px; border-radius: 8px; background: var(--subtle-fg, var(--control-bg)); }
.epasi-today header, .epasi-today li { display: flex; justify-content: space-between; gap: 8px; }
.epasi-today ul { list-style: none; margin: 8px 0 0; padding: 0; display: flex; flex-direction: column; gap: 4px; color: var(--text-muted); }
.epasi-today a { color: var(--text-color); min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.epasi-today small { color: var(--text-muted); }
.epasi-today li span { white-space: nowrap; }
.epasi-today .muted { color: var(--text-muted); }
.epasi-today em { font-style: normal; font-size: 12px; }
.epasi-today .up { color: var(--green-600, green); }
.epasi-today .down { color: var(--red-600, red); }
